        mechatronics: { kind: 'engineering_lab', task: details.lab, deliverable: 'Sơ đồ/mô hình + thông số + kết quả đo + phân tích sai số' },
        general: { kind: 'practical', task: details.lab, checklist: ['Đọc brief','Thực hiện','Kiểm tra','Giải thích kết quả'] }
