    const quickChecks = unique([...(base.quickChecks || []), topicRecipe.check, `Input/output của ${topic.toLowerCase()} là gì?`, 'Tiêu chí nào xác nhận task đã đạt?', 'Edge case hoặc distractor nào cần chú ý?', 'Lựa chọn hiện tại dựa trên evidence nào?', 'Skill nào cần retest trước khi tăng difficulty?']).slice(0, 8);
    const glossary = unique([topic, ...(base.glossary || []), ...details.sections]).slice(0, 16);
    return { ...base, theorySections, theory, lecture: { title: `Bài giảng: ${topic}`, script: baseLecture, keyPoints: ['Hiểu bối cảnh', 'Nắm kiến thức', 'Làm theo quy trình', 'Thực hành', 'Timed task', 'Review lỗi', 'Retest'] }, examples, activities, practiceTasks, commonMistakes, quickChecks, glossary, domain, contentWordCount: words(theory), domainName: details.domainName, practical: defaultPractical, practicalProfile: topicRecipe.independent, topicRecipe, contentQualityStatus: 'AUTO_GENERATED_REQUIRES_TEACHER_REVIEW' };
