            { type: 'essay', prompt: `Giải thích trade-off giữa độ chính xác, chi phí và độ phức tạp khi thiết kế hệ ${topic.toLowerCase()}.`, options: [], rubric: { criteria: [{ name: 'Technical reasoning', points: 4 }, { name: 'Trade-off', points: 3 }, { name: 'Evidence', points: 3 }], maxScore: 10 }, explanation: 'Đánh giá tư duy kỹ thuật.', points: 10, difficulty: 'HARD', skill },
            { type: 'reading_comprehension', prompt: 'Đọc mô tả lab và chọn thao tác giúp tăng độ tin cậy của kết quả.', options: ['Ghi điều kiện thử và lặp phép đo','Đổi nhiều thông số cùng lúc','Bỏ qua calibration','Chỉ ghi giá trị cuối'].map(label => ({ label, value: label })), answer: 'Ghi điều kiện thử và lặp phép đo', explanation: 'Lặp và ghi điều kiện giúp phân tích sai số.', points: 2, difficulty: 'MEDIUM', skill, media: { passage: 'A student repeats measurements under the same conditions and records the setup before comparing the results.' } },
            { type: 'timed_simulation', prompt: `Timed lab planning: trong 20 phút, lập kế hoạch thử nghiệm cho ${topic.toLowerCase()}.`, options: [], rubric: { criteria: [{ name: 'Setup', points: 3 }, { name: 'Measurement plan', points: 4 }, { name: 'Safety', points: 3 }], maxScore: 10 }, explanation: 'Mô phỏng nhiệm vụ lab có bấm giờ.', points: 10, difficulty: 'HARD', skill, media: { kind: 'engineering_timed', durationSeconds: 1200, checklist: ['Mục tiêu','Thiết lập','Đo','An toàn','Tiêu chí'] } }
